// 'Danger signs if any?' is 'Yes' AND ('Blood Pressure (Systolic)' > 140 OR ('Urine Albumin' is 'Positive' AND 'Blood sugar' is 'Positive'))
const dangerSigns = new imports.rulesConfig.RuleCondition({programEncounter}).when.valueInEncounter('Danger signs if any?').containsAnswerConceptName('Yes').matches();
const highSystolic = new imports.rulesConfig.RuleCondition({programEncounter}).when.valueInEncounter('Blood Pressure (Systolic)').greaterThan(140).matches();
const albuminAndSugar = new imports.rulesConfig.RuleCondition({programEncounter}).when.valueInEncounter('Urine Albumin').containsAnswerConceptName('Positive').and.when.valueInEncounter('Blood sugar').containsAnswerConceptName('Positive').matches();
const visibility = dangerSigns && (highSystolic || albuminAndSugar);
